class _DoctorsState extends State<DoctorsTab>{late Future<List<Map<String,dynamic>>> future;@override void initState(){super.initState();future=widget.api.listDoctors();}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Find a Doctor')),body:FutureBuilder<List<Map<String,dynamic>>>(future:future,builder:(c,s){if(s.connectionState==ConnectionState.waiting)return const Center(child:CircularProgressIndicator());if(s.hasError)return const Center(child:Text('Unable to load doctors.'));final ds=s.data??[];return ListView(padding:const EdgeInsets.all(16),children:ds.map((d)=>Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.person)),title:Text('${d['name']}'),subtitle:Text('${d['specialty']}'),trailing:FilledButton(onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>BookingPage(api:widget.api,doctorId:int.tryParse('${d['id']}'),doctorName:'${d['name']}'))),child:const Text('Book'))))).toList());}));}}
class BookingPage extends StatefulWidget{const BookingPage({super.key,required this.api,this.doctorId,this.doctorName});final ApiService api;final int? doctorId;final String? doctorName;@override State<BookingPage> createState()=>_BookingState();}
class _BookingState extends State<BookingPage>{DateTime? date;String? slot;String mode='Video';bool loading=false,saving=false;List<String> slots=[];final patient=TextEditingController();final phone=TextEditingController();Future<void>loadSlots(DateTime d)async{if(widget.doctorId==null)return;setState(()=>loading=true);try{slots=await widget.api.availableSlots(widget.doctorId!,d);slot=null;}catch(e){slots=[];}finally{if(mounted)setState(()=>loading=false);}}Future<void>pickDate()async{if(widget.doctorId==null)return;final d=await showDatePicker(context:context,firstDate:DateTime.now(),lastDate:DateTime.now().add(const Duration(days:90)),initialDate:date??DateTime.now());if(d!=null){setState(()=>date=d);await loadSlots(d);}}Future<void>book()async{if(widget.doctorId==null||date==null||slot==null||patient.text.trim().isEmpty||phone.text.trim().isEmpty){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Please complete patient details and select an available slot.')));return;}final p=slot!.split(':');final appointment=DateTime(date!.year,date!.month,date!.day,int.parse(p[0]),int.parse(p[1]));setState(()=>saving=true);try{await widget.api.createAppointment(patientName:patient.text.trim(),phone:phone.text.trim(),doctorId:widget.doctorId!,appointmentAt:appointment,mode:mode);if(mounted){await showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('Appointment Confirmed ✓'),content:Text('Your $mode appointment with ${widget.doctorName??'the doctor'} is confirmed for $slot.'),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Done'))]));Navigator.pop(context,true);}}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString().replaceFirst('Exception: ',''))));}finally{if(mounted)setState(()=>saving=false);}}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Book Appointment')),body:ListView(padding:const EdgeInsets.all(16),children:[Text(widget.doctorName??'Choose a doctor',style:const TextStyle(fontSize:20,fontWeight:FontWeight.bold)),const SizedBox(height:16),TextField(controller:patient,decoration:const InputDecoration(labelText:'Patient name',prefixIcon:Icon(Icons.person),border:OutlineInputBorder())),const SizedBox(height:12),TextField(controller:phone,keyboardType:TextInputType.phone,decoration:const InputDecoration(labelText:'Mobile number',prefixIcon:Icon(Icons.phone),border:OutlineInputBorder())),const SizedBox(height:16),OutlinedButton.icon(onPressed:pickDate,icon:const Icon(Icons.calendar_month),label:Text(date==null?'Choose date':'${date!.day}/${date!.month}/${date!.year}')),if(date!=null)...[const SizedBox(height:16),const Text('Available time slots',style:TextStyle(fontSize:17,fontWeight:FontWeight.bold)),const SizedBox(height:8),if(loading)const Center(child:CircularProgressIndicator())else if(slots.isEmpty)const Text('No available slots for this date.')else Wrap(spacing:8,runSpacing:8,children:slots.map((s)=>ChoiceChip(label:Text(s),selected:slot==s,onSelected:(_)=>setState(()=>slot=s))).toList())],const SizedBox(height:16),DropdownButtonFormField<String>(initialValue:mode,decoration:const InputDecoration(labelText:'Consultation mode',border:OutlineInputBorder()),items:const[DropdownMenuItem(value:'Video',child:Text('Video consultation')),DropdownMenuItem(value:'In-clinic',child:Text('In-clinic visit'))],onChanged:(v)=>setState(()=>mode=v!)),const SizedBox(height:22),FilledButton.icon(onPressed:saving?null:book,icon:const Icon(Icons.check_circle),label:Text(saving?'Confirming...':'Confirm Appointment'))]));@override void dispose(){patient.dispose();phone.dispose();super.dispose();}}
class BookingsTab extends StatelessWidget{const BookingsTab({super.key,required this.api});final ApiService api;@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('My Bookings')),body:FutureBuilder<List<Map<String,dynamic>>>(future:api.listAppointments(),builder:(c,s){if(s.connectionState==ConnectionState.waiting)return const Center(child:CircularProgressIndicator());if(s.hasError)return const Center(child:Text('Unable to load bookings.'));final a=s.data??[];return ListView(padding:const EdgeInsets.all(16),children:[if(a.isEmpty)const Card(child:ListTile(title:Text('No appointments yet'),subtitle:Text('Book a consultation to see it here.'))),...a.map((x)=>Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.calendar_today)),title:Text('Doctor #${x['doctorId']}'),subtitle:Text('${x['appointmentAt']} • ${x['mode']}'),trailing:Text('${x['status']??'confirmed'}'))))]);}));}}
class ProfileTab extends StatefulWidget{const ProfileTab({super.key,required this.api});final ApiService api;@override State<ProfileTab> createState()=>_ProfileState();}
class _ProfileState extends State<ProfileTab>{final name=TextEditingController(),phone=TextEditingController(),emergency=TextEditingController(),member=TextEditingController(),relation=TextEditingController();bool loading=true,saving=false;List<Map<String,dynamic>> family=[];@override void initState(){super.initState();_load();}Future<void>_load()async{try{final p=await widget.api.getProfile();final f=await widget.api.listFamilyMembers();if(!mounted)return;name.text='${p['name']??''}';phone.text='${p['phone']??''}';emergency.text='${p['emergencyContact']??''}';setState(()=>family=f);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Could not load profile: $e')));}finally{if(mounted)setState(()=>loading=false);}}Future<void>_save()async{setState(()=>saving=true);try{await widget.api.updateProfile(name:name.text.trim(),phone:phone.text.trim(),emergencyContact:emergency.text.trim());if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Profile saved successfully ✓')));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString().replaceFirst('Exception: ',''))));}finally{if(mounted)setState(()=>saving=false);}}Future<void>_add()async{if(member.text.trim().isEmpty||relation.text.trim().isEmpty)return;try{final x=await widget.api.addFamilyMember(name:member.text.trim(),relation:relation.text.trim());setState(()=>family=[...family,x]);member.clear();relation.clear();if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Family member added ✓')));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString().replaceFirst('Exception: ',''))));}}@override Widget build(BuildContext c){if(loading)return const Scaffold(body:Center(child:CircularProgressIndicator()));return Scaffold(appBar:AppBar(title:const Text('My Profile')),body:ListView(padding:const EdgeInsets.all(16),children:[const Center(child:CircleAvatar(radius:42,child:Icon(Icons.person,size:44))),const SizedBox(height:18),_field(name,'Full name',Icons.person),_field(phone,'Mobile number',Icons.phone,TextInputType.phone),_field(emergency,'Emergency contact',Icons.contact_phone,TextInputType.phone),FilledButton.icon(onPressed:saving?null:_save,icon:const Icon(Icons.save),label:Text(saving?'Saving...':'Save Profile')),const SizedBox(height:28),const Text('Family Members',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),const SizedBox(height:8),if(family.isEmpty)const Card(child:ListTile(title:Text('No family members yet.'))),...family.map((f)=>Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.person)),title:Text('${f['name']??'Member'}'),subtitle:Text('${f['relation']??''}')))),const SizedBox(height:8),_field(member,'Family member name',Icons.group),_field(relation,'Relation',Icons.people),OutlinedButton.icon(onPressed:_add,icon:const Icon(Icons.person_add),label:const Text('Add Family Member'))]));}Widget _field(TextEditingController x,String label,IconData i,[TextInputType? k])=>Padding(padding:const EdgeInsets.only(bottom:12),child:TextField(controller:x,keyboardType:k,decoration:InputDecoration(labelText:label,prefixIcon:Icon(i),border:const OutlineInputBorder())));@override void dispose(){name.dispose();phone.dispose();emergency.dispose();member.dispose();relation.dispose();super.dispose();}}
